<?php /** @var array $rows $top $users */ ?>
<div class="page-head"><div><div class="eyebrow">Контроль и аналитика</div><h1>Журнал действий</h1><div class="sub">кто и какими функциями пользовался</div></div></div>
<?php if (!$auditReady): ?><div class="notice warning">Журнал ещё не активирован. Примените миграцию базы <code>schema23.sql</code> после резервного копирования.</div><?php endif; ?>
<div class="card"><form class="filters" method="get"><input type="hidden" name="p" value="audit"><select name="user"><option value="0">Все сотрудники</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>" <?= $user===(int)$u['id']?'selected':'' ?>><?= e($u['name']) ?></option><?php endforeach; ?></select><input name="action" value="<?= e($action) ?>" placeholder="Функция"><input type="date" name="from" value="<?= e($from) ?>"><input type="date" name="to" value="<?= e($to) ?>"><button class="btn primary">Показать</button></form></div>
<?php if ($top): ?><div class="card"><h2>Часто используемые функции</h2><div class="audit-top"><?php foreach($top as $t): ?><div><span><?= e($t['action']) ?></span><strong><?= (int)$t['total'] ?></strong></div><?php endforeach; ?></div></div><?php endif; ?>
<div class="card"><h2>Последние действия</h2><?php if (!$rows): ?><p class="muted">Записей нет.</p><?php else: ?><div class="logfeed"><?php foreach($rows as $r): ?><div class="lg-row"><div class="lg-top"><span class="lg-time"><?= e(date('d.m.Y H:i',strtotime($r['created_at']))) ?></span><span class="badge <?= $r['result']==='failure'?'err':'ok' ?>"><?= e($r['result']) ?></span><strong><?= e($r['action']) ?></strong><span class="muted"><?= e($r['actor_name']) ?></span><?php if($r['entity_type']): ?><span class="faint"><?= e($r['entity_type']) ?> #<?= (int)$r['entity_id'] ?></span><?php endif; ?></div></div><?php endforeach; ?></div><?php endif; ?></div>
